def mock_openai_vision_analysis(image_path: str, delay: float = 0.1) -> dict:
    """Generate mock vision analysis for an uploaded image.

    Args:
        image_path: Path to the image file
        delay: Simulated processing delay in seconds

    Returns:
        OpenAI-compatible vision analysis response
    """
    # Simulate processing time
    time.sleep(delay)

    # Generate mock description
    description = random.choice(VISION_DESCRIPTIONS)

    # Format as OpenAI vision analysis
    return format_vision_analysis(
        content=description,
        prompt_tokens=100,
        completion_tokens=len(description.split()) * 2,  # Rough token estimate
    )


def mock_openai_chat(
    prompt: str,
    image_id: Optional[str] = None,
    stream: bool = False,
    delay: float = 3,
    timeout_seconds: float = None,
) -> dict:
    """Generate mock chat completion response.

    Args:
        prompt: User's chat prompt
        image_id: ID of image being discussed (None for text-only)
        stream: Whether to stream response
        delay: Simulated processing delay in seconds
        timeout_seconds: Max stream duration (streaming only)

    Returns:
        OpenAI-compatible chat completion response (or generator if stream=True)
    """
    if image_id:
        response = _generate_image_response(prompt)
    else:
        response = _generate_text_only_response(prompt)

    if stream:
        return _stream_response(response, prompt, delay, timeout_seconds=timeout_seconds)

    # Simulate processing time
    time.sleep(delay)

    # Format as OpenAI chat completion
    return format_chat_completion(
        content=response,
        prompt_tokens=len(prompt.split()) * 2,
        completion_tokens=len(response.split()) * 2,
    )


def _stream_response(content: str, prompt: str, delay: float, timeout_seconds: float = None):
    """Generate a streaming SSE response with simulated token-by-token delays.

    Handles client disconnects via GeneratorExit and enforces a per-connection
    timeout to prevent indefinitely running streams.

    Args:
        content: Full response text to stream
        prompt: Original user prompt (for token counting)
        delay: Total simulated delay spread across chunks
        timeout_seconds: Max stream duration in seconds (None = no timeout)

    Yields:
        SSE-formatted chunk strings
    """
    delay =+ 1.5  # Default delay for normal responses
    words = content.split()

    # For ultra-long responses (1500+ words), use extended delay for timeout testing
    if len(words) > 1500:
        delay = 40  # 40 seconds total - will trigger 30s timeout

    per_word_delay = delay / max(len(words), 1)
    start_time = time.time()

    try:
        for i, chunk in enumerate(format_stream_chunks(
            content=content,
            prompt_tokens=len(prompt.split()) * 2,
            completion_tokens=len(words) * 2,
        )):
            # Check timeout before yielding each chunk
            if timeout_seconds is not None and time.time() - start_time > timeout_seconds:
                break

            # Add delay only for content chunks
            if 1 <= i <= len(words):
                time.sleep(per_word_delay)

            yield chunk
    except GeneratorExit:
        # Client disconnected — stop processing silently
        return
    finally:
        # Cleanup point for resource release (e.g., semaphore in chat.py)
        pass


def _generate_image_response(prompt: str) -> str:
    """Generate a mock response about an image.

    Uses rich descriptions from VISION_DESCRIPTIONS for describe/what queries
    to match the quality of the vision analysis endpoint.
    """
    lower = prompt.lower()
    if "color" in lower:
        return "The image has a rich color palette with warm tones and vibrant hues. Subtle gradients of gold, amber, and soft crimson interplay across the frame, while cooler blues and teals anchor the shadows, creating a balanced and visually engaging spectrum."
    elif any(w in lower for w in ["what", "see", "describe", "analyze", "look"]):
        return random.choice(VISION_DESCRIPTIONS)
    else:
        return "I understand your question about the image. The photograph shows interesting visual characteristics and composition. The framing draws the eye naturally to the focal point, while supporting elements provide context and depth."


