def _generate_text_only_response(prompt: str) -> str:
    """Generate a mock response for text-only conversation (no image)."""
    lower = prompt.lower().strip()

    # Ultra-long responses for timeout testing
    if any(w in lower for w in ["extremely long", "very long", "long detailed", "many many paragraphs", "long story"]):
        return random.choice(TEXT_ONLY_RESPONSES["long_story"])
    elif any(w in lower for w in ["hello", "hi", "hey", "greetings", "good morning", "good afternoon", "good evening"]):
        return random.choice(TEXT_ONLY_RESPONSES["greeting"])
    elif any(w in lower for w in ["help", "what can you do", "how do", "how does", "capabilities"]):
        return random.choice(TEXT_ONLY_RESPONSES["help"])
    else:
        return random.choice(TEXT_ONLY_RESPONSES["general"])
